// Throwaway style 02: does a navy sidebar + paired objective/goals workspace feel clear?
const initial=()=>({signed:true,page:'focus',name:'Jordan Davis',role:'member',status:'Draft',objective:'Build and release a clearer next-step screen for one video devotional, using AI to help write code.',goals:[{text:'Test 20 viewers; count who find the next step.',when:'Month 1',target:'20 viewers'},{text:'Release after accessibility and reliability checks.',when:'Month 3',target:'Complete checks'},{text:'Retest 20 viewers; at least 16 find the next step.',when:'Month 6',target:'At least 16 of 20'}],notes:'',gaps:'Viewer needs unclear → Confirm with Product.',development:'Lead technical design and AI code reviews.',leadership:'',devGoals:'Month 2: Compare 2 build options; recommend one to Product.\nMonth 6: Record 3 AI code reviews and fixes.',comments:[{who:'Casey Morgan · Career lead',text:'Let’s discuss how the viewer test will show a clearer next step.'}],memberAgree:false,leadAgree:false,saved:'Not saved yet',notifications:[{id:1,title:'Discuss your draft with Casey',body:'Casey has added a discussion prompt. Review timing: ask your career lead.',page:'review',read:false},{id:2,title:'Your position focus is ready to draft',body:'Use the engineering example if you need a starting point.',page:'focus',read:false}],members:[{name:'Jordan Davis',role:'Member'},{name:'Casey Morgan',role:'Career lead'}],guide:'Example',step:0,pref:true});let s=initial();let query='';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(text,action,cls='')=>`<button class="${cls}" onclick="${action}">${text}</button>`;
const field=(label,key,value,area=false)=>`<label>${label}${area?`<textarea oninput="s.${key}=this.value;dirty()">${esc(value)}</textarea>`:`<input value="${esc(value)}" oninput="s.${key}=this.value;dirty()">`}</label>`;
const visual=()=>'<div class="visual"><div><b class="symbol">♙</b><b>People</b>Viewers of one devotional</div><span>→</span><div><b class="symbol">◎</b><b>Outcome</b>Find a clear next step</div><span>→</span><div><b class="symbol">▥</b><b>Contribution</b>More people take a next step</div></div>';
function dirty(){s.saved='Unsaved changes';s.memberAgree=false;s.leadAgree=false;if(s.status==='Agreed')s.status='Refining';updateState()}
function toast(t){let el=document.getElementById('toast');el.textContent=t;el.style.display='block';clearTimeout(window.tt);window.tt=setTimeout(()=>el.style.display='none',3500)}
function go(page){s.page=page;query='';render();window.scrollTo(0,0)}
function save(){s.saved='Saved in this session';render();toast('Draft saved in memory. Refreshing clears this demo.')}
function updateState(){let e=document.getElementById('state');if(e)e.textContent=JSON.stringify(s,null,2)}
function reset(){s=initial();query='';render();toast('Demo reset')}
function render(){let app=document.getElementById('app');if(!s.signed){app.innerHTML=`<div class="signed-out card"><div class="brand">♙ Lantern</div><h1>Your next step starts here.</h1><p class="muted">Prototype sign-in · synthetic accounts only.</p><label>Demo account<select id="signin"><option value="member">Jordan Davis — member</option><option value="lead">Casey Morgan — career lead</option></select></label>${btn('Sign in to demo',"s.role=document.getElementById('signin').value;s.signed=true;go('work')",'primary')}<p class="stateless">No Google connection. Your session data stays in memory.</p></div>`;return}let titles={work:'My work',focus:'My position focus',review:'Discuss & refine',inbox:'Inbox',department:'Department',guide:'A position focus in practice',account:'Account settings'};let nav=[['work','⌂','My work'],['focus','◎','Position focus'],['review','◯','Discuss & review'],['inbox','✉','Inbox'],['department','♙','Department'],['guide','▤','Guide'],['account','⚙','Account']];app.innerHTML=`<aside><div class="brand"><span>♙</span> Lantern</div><nav>${nav.map(([id,icon,label])=>btn(`<span>${icon}</span>${label}${id==='inbox'?` <span class="badge">${s.notifications.filter(n=>!n.read).length}</span>`:''}`,`go('${id}')`,s.page===id?'active':'')).join('')}</nav><div class="aside-foot">A clear next step<br><strong>for more people.</strong><hr>02 / Navy operations</div></aside><main class="main"><div class="demo"><span><b>PROTOTYPE</b> · In-memory only · All people and actions are simulated</span>${btn('Reset demo','reset()')}</div><header><div><small>${s.page==='guide'?'Guide':'Digital Ministry Team'}</small><h1>${titles[s.page]}</h1><p class="muted">${s.page==='focus'?'Define your objective and goals for your current position.':s.page==='guide'?'Short explanations. One complete, illustrative example.':''}</p></div>${btn(`<span class="avatar">${s.role==='lead'?'CM':'JD'}</span><span>${s.role==='lead'?'Casey Morgan':esc(s.name)}<br><small>${s.role==='lead'?'Career lead':'Department member'}</small></span>`,"go('account')",'account')}</header>${({work:home,focus:focus,review:review,inbox:inbox,department:department,guide:guide,account:account})[s.page]()}<details class="state"><summary>Prototype state · inspect temporary data</summary><pre id="state"></pre></details></main>`;updateState()}
function flow(){return `<div class="workflow">${[['Draft','In progress'],['Discuss','With your career lead'],['Refine','Incorporate input'],['Agree','Joint agreement']].map(([t,d],i)=>btn(`<b>${i+1}. ${t}</b><small>${d}</small>`,i===0?"go('focus')":i===2?"s.status='Refining';go('focus')":"go('review')",(s.status==='Draft'&&i===0||s.status==='Discussing'&&i===1||s.status==='Refining'&&i===2||s.status==='Agreed'&&i===3)?'current':'')).join('')}</div>`}
function home(){return `<div class="home-hero"><span class="badge">${s.status}</span><h2>A clear next step for your position</h2><p>${esc(s.objective)}</p>${btn('Continue my position focus',"go('focus')",'primary')}</div><div class="grid"><section class="card"><h2>Discuss with Casey</h2><p>Bring your objective, draft goals and open questions to your career lead.</p><p class="muted">Review timing: ask your career lead.</p>${btn('Open discussion',"go('review')")}</section><section class="card"><h2>Need a starting point?</h2><p>See an objective beside its SMART goals, then return to your draft.</p>${btn('View the worked example',"s.guide='Example';go('guide')")}</section></div><section class="card"><div class="row"><h2>Capture a thought</h2>${btn('Save note','save()','primary')}</div>${field('Notes for my position focus','notes',s.notes,true)}</section>`}
function focus(){return `${flow()}<div class="grid"><section class="card"><div class="row"><h2>Critical mission objective</h2>${btn('How it fits together',"s.guide='Objectives';go('guide')",'link')}</div><p class="muted">What is the most important outcome you’re working to achieve?</p>${visual()}<label class="muted">My objective<textarea class="objective" oninput="s.objective=this.value;dirty()">${esc(s.objective)}</textarea></label></section><section class="card"><div class="row"><h2>Goals</h2>${btn('+ Add goal','goalDialog()','primary')}</div><p class="muted">A few SMART goals that support your objective.</p>${s.goals.map((g,i)=>`<div class="goal"><div class="row"><b>${i+1}. ${esc(g.text)}</b><div class="stack">${btn('Edit',`goalDialog(${i})`,'link')}${btn('Delete',`removeGoal(${i})`,'link danger')}</div></div><div class="grid"><div><label>Target</label>${esc(g.target)}</div><div><label>Target time</label>${esc(g.when)}</div></div></div>`).join('')||'<p class="empty">Add your first supporting goal.</p>'}</section></div><div class="grid"><section class="card"><h2>Notes</h2>${field('Context, ideas and considerations','notes',s.notes,true)}</section><section class="card"><h2>Gaps & next steps</h2>${field('What needs to be true for you to make progress?','gaps',s.gaps,true)}<details><summary>Optional development</summary>${field('Personal development','development',s.development,true)}${field('Development goals','devGoals',s.devGoals,true)}${field('Leadership development','leadership',s.leadership,true)}</details></section></div><div class="footer"><span><b>Review timing</b> · Ask your career lead.<br><small>${esc(s.saved)}</small></span><div class="stack">${btn('Save draft','save()')}${btn('Discuss with career lead',"s.status='Discussing';go('review')",'primary')}</div></div>`}
function modal(html){let m=document.getElementById('modal');m.innerHTML=html;m.showModal()}
function closeModal(){document.getElementById('modal').close()}
function goalDialog(i=-1){let g=s.goals[i]||{text:'',target:'',when:''};modal(`<h2>${i<0?'Add':'Edit'} goal</h2><form onsubmit="event.preventDefault();storeGoal(${i})"><label>Goal<textarea id="gt" required>${esc(g.text)}</textarea></label><div class="grid"><label>Measurable target<input id="gm" required value="${esc(g.target)}"></label><label>Target time<input id="gw" required value="${esc(g.when)}" placeholder="Agree a timeframe"></label></div><p class="muted">Be specific about what will change and how you’ll know.</p><div class="stack"><button class="primary" type="submit">Save goal</button><button type="button" onclick="closeModal()">Cancel</button></div></form>`)}
function storeGoal(i){let g={text:document.getElementById('gt').value,target:document.getElementById('gm').value,when:document.getElementById('gw').value};if(i<0)s.goals.push(g);else s.goals[i]=g;dirty();closeModal();render();toast('Goal updated in your draft')}
function removeGoal(i){modal(`<h2>Delete this goal?</h2><p>${esc(s.goals[i].text)}</p><div class="stack">${btn('Delete goal',`s.goals.splice(${i},1);dirty();closeModal();render();toast('Goal deleted')`,'danger')}${btn('Keep goal','closeModal()')}</div>`)}
function review(){return `${flow()}<div class="notice">Discussion simulation. Nothing is sent to another person. Review timing: ask your career lead.</div><div class="grid"><section class="card"><div class="row"><h2>Draft to discuss</h2><span class="badge">${s.status}</span></div><p>${esc(s.objective)}</p>${s.goals.map(g=>`<div class="timeline"><strong>${esc(g.when)}</strong><span>${esc(g.text)}</span></div>`).join('')}${btn('Refine my draft',"s.status='Refining';go('focus')")}</section><section class="card"><h2>Conversation with Casey</h2>${s.comments.map(c=>`<div class="list-item"><b>${esc(c.who)}</b><p>${esc(c.text)}</p></div>`).join('')}<form onsubmit="event.preventDefault();addComment()"><label>Add a discussion note<textarea id="comment" required placeholder="What would you like to discuss?"></textarea></label><button class="primary" type="submit">Add note to simulation</button></form></section></div><section class="card"><h2>Agree together</h2><p>Both people agree on the same draft. Editing the focus clears agreement so it can be revisited.</p><div class="stack">${btn(s.memberAgree?'✓ Jordan agrees':'Simulate Jordan’s agreement',"agree('memberAgree')",s.memberAgree?'':'primary')}${btn(s.leadAgree?'✓ Casey agrees':'Simulate Casey’s agreement',"agree('leadAgree')")}${btn('Reopen for revision',"s.memberAgree=false;s.leadAgree=false;s.status='Refining';go('focus')")}</div><p class="muted">${s.status==='Agreed'?'Joint agreement recorded in this demo only.':'Awaiting both participants. No automatic approval.'}</p></section>`}
function agree(k){s[k]=!s[k];s.status=s.memberAgree&&s.leadAgree?'Agreed':'Discussing';render();toast(s.status==='Agreed'?'Simulated joint agreement recorded':'Agreement updated')}
function addComment(){let text=document.getElementById('comment').value.trim();if(!text)return;s.comments.push({who:s.role==='lead'?'Casey Morgan · Career lead':s.name+' · Member',text});render();toast('Discussion note added locally')}
function inbox(){return `<section class="card"><div class="row"><h2>Your notifications</h2>${btn('Mark all read',"s.notifications.forEach(n=>n.read=true);render()")}</div>${s.notifications.map(n=>`<article class="list-item ${!n.read?'unread':''}"><div class="row"><h3>${!n.read?'● ':''}${esc(n.title)}</h3><small>Demo notification</small></div><p>${s.pref?esc(n.body):"Notification preview hidden in account preferences."}</p><div class="stack">${btn('Open task',`openNotification(${n.id})`,'primary')}${btn(n.read?'Mark unread':'Mark read',`toggleNotification(${n.id})`)}${btn('Dismiss',`s.notifications=s.notifications.filter(n=>n.id!==${n.id});render()`,'link')}</div></article>`).join('')||'<div class="empty">You’re all caught up.</div>'}</section>`}
function openNotification(id){let n=s.notifications.find(n=>n.id===id);n.read=true;go(n.page)}function toggleNotification(id){let n=s.notifications.find(n=>n.id===id);n.read=!n.read;render()}
function department(){return `<section class="card"><div class="row"><div><h2>Digital Ministry Team</h2><p class="muted">${s.members.length} members · Casey Morgan, career lead</p></div>${s.role==='lead'?btn('+ Add registered user','addMemberDialog()','primary'):btn('Try career-lead view',"s.role='lead';render();toast('Switched to simulated career lead')")}</div><p class="muted">${s.role==='lead'?'Career-lead permissions: assign eligible registered people to this department.':'Member view. Your career lead manages department assignment.'}</p><label>Find a member<input value="${esc(query)}" oninput="query=this.value;renderRoster()" placeholder="Search name"></label><div id="roster"></div></section>`}
function renderRoster(){let el=document.getElementById('roster');if(el)el.innerHTML=s.members.filter(m=>m.name.toLowerCase().includes(query.toLowerCase())).map(m=>`<div class="list-item row"><div><b>${esc(m.name)}</b><br><small>${m.role}</small></div>${btn('View member',`memberDetail('${m.name}')`)}</div>`).join('')||'<p class="empty">No matching members.</p>'}
function memberDetail(name){let m=s.members.find(m=>m.name===name);modal(`<h2>${esc(m.name)}</h2><p>${m.role} · Digital Ministry Team</p><p>Registered synthetic account · Active membership</p><p class="muted">Position-focus content stays in the work and discussion screens.</p><div class="stack">${s.role==='lead'&&m.role!=='Career lead'?btn('Remove from department',`s.members=s.members.filter(m=>m.name!=='${m.name}');closeModal();render();toast('Membership removed in demo')`,'danger'):''}${btn('Close','closeModal()')}</div>`)}
function addMemberDialog(){modal(`<h2>Add a registered user</h2><p class="muted">Select an eligible registered person. No invitation is sent.</p><label>Registered people<select id="candidate"><option value="Alex Rivera">Alex Rivera — eligible, unassigned</option><option disabled>Jordan Davis — already assigned / existing member</option><option disabled>Sam Lee — former department member</option><option disabled>Taylor Reed — assigned to another department</option></select></label><div class="stack">${btn('Add to department',"addMember()",'primary')}${btn('Cancel','closeModal()')}</div>`);if(s.members.some(m=>m.name==='Alex Rivera')){document.getElementById('candidate').options[0].disabled=true;document.querySelector('#modal .primary').disabled=true}}
function addMember(){s.members.push({name:'Alex Rivera',role:'Member'});closeModal();render();toast('Alex added to the simulated department')}
function guide(){let tabs=['Objectives','SMART goals','Example'];return `<div class="tabs">${tabs.map(t=>btn(t,`s.guide='${t}';s.step=0;render()`,s.guide===t?'active':'')).join('')}</div>${s.guide==='Example'?example():lesson()}<div class="footer"><span>Illustrative targets · Agree review timing with your career lead.</span>${btn('Back to my position focus',"go('focus')",'primary')}</div>`}
function example(){return `<span class="badge">Illustrative engineering example</span><div class="grid" style="margin-top:16px"><section class="card"><h2>Critical mission objective</h2><p class="muted">What are you working to achieve in this position?</p><div class="sample">Build and release a clearer next-step screen for one video devotional, using AI to help write code.${visual()}</div></section><section class="card"><h2>SMART goals</h2><p class="muted">Specific, measurable, achievable, relevant and time-bound.</p>${[['Month 1','Test 20 viewers; count who find the next step.'],['Month 3','Release after accessibility and reliability checks.'],['Month 6','Retest 20 viewers; at least 16 find the next step.']].map(([a,b])=>`<div class="timeline"><strong>${a}</strong><span>${b}</span></div>`).join('')}</section></div><div class="grid"><section class="card"><h2>Personal development · optional</h2><p class="muted">What could help you grow in this position?</p><div class="sample">Lead technical design and AI code reviews.</div></section><section class="card"><h2>Development goals</h2><div class="timeline"><strong>Month 2</strong><span>Compare 2 build options; recommend one to Product.</span></div><div class="timeline"><strong>Month 6</strong><span>Record 3 AI code reviews and fixes.</span></div></section></div><div class="notice"><b>Gaps / next step</b>　Viewer needs unclear → Confirm with Product.</div>`}
function lesson(){let objectives=[['Start with people','Who should benefit from your work?','Viewers of one video devotional'],['Name the outcome','What should become clearer or easier for those people?','Find a clear next step after watching'],['Show your contribution','What will you build or change to help that outcome?','Build and release a clearer next-step screen']];let smart=[['Make it specific and measurable','Name the work and what evidence you’ll collect.','Test 20 viewers; count who find the next step.'],['Check achievable and relevant','Agree scope, capacity and why this supports the objective.','One video devotional. Confirm viewer needs with Product.'],['Make it time-bound','Agree when you’ll check the result.','By Month 6, retest 20; at least 16 find the next step.']];let steps=s.guide==='Objectives'?objectives:smart;let item=steps[s.step];return `<section class="card"><small>STEP ${s.step+1} OF 3 · ${s.guide.toUpperCase()}</small><h2>${item[0]}</h2><p class="muted">${item[1]}</p>${s.guide==='Objectives'?visual():'<div class="visual"><div><b>S</b>Specific</div><div><b>M</b>Measurable</div><div><b>A</b>Achievable</div><div><b>R</b>Relevant</div><div><b>T</b>Time-bound</div></div>'}<div class="sample">${item[2]}</div><div class="row" style="margin-top:24px"><button onclick="s.step--;render()" ${s.step===0?'disabled':''}>← Previous</button><span>${s.step+1} / 3</span>${s.step<2?btn('Next →','s.step++;render()','primary'):btn('See complete example',"s.guide='Example';render()",'primary')}</div></section>`}
function account(){return `<div class="grid"><section class="card"><h2>Profile</h2><p class="muted">Synthetic account · changes stay in this browser session.</p>${field('Member display name','name',s.name)}<label>Email<input value="jordan@example.test" readonly></label><p><small>Digital Ministry Team · ${s.role==='lead'?'Career lead':'Member'}</small></p>${btn('Save profile','save()','primary')}</section><section class="card"><h2>Preferences</h2><label class="check"><input type="checkbox" ${s.pref?'checked':''} onchange="s.pref=this.checked;updateState();toast('Demo preference updated')">Show notification previews</label><p class="muted">Review timing is agreed with your career lead; no schedule is configured.</p><h3>Explore permissions</h3><label>Current demo role<select onchange="s.role=this.value;render();toast('Demo role changed')"><option value="member" ${s.role==='member'?'selected':''}>Jordan — department member</option><option value="lead" ${s.role==='lead'?'selected':''}>Casey — career lead</option></select></label>${btn('Sign out of demo',"s.signed=false;render()")}</section></div>`}
const renderBase=render;render=function(){renderBase();if(s.signed&&s.page==='department')renderRoster()};render();
